package cn.wenjin.admission.web;

import cn.wenjin.admission.data.AdmissionDataRepository;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1") public class PublicDataController {private final AdmissionDataRepository data;public PublicDataController(AdmissionDataRepository d){data=d;}@GetMapping("/universities/search")Object schools(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="20")int limit){return data.search(q,limit);}@GetMapping("/majors/search")Object majors(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="20")int limit){return data.search(q,limit).stream().filter(x->x.majorName()!=null).toList();}@GetMapping("/sources/{id}")Object source(@PathVariable String id){return data.findSource(id).orElseThrow(()->new IllegalArgumentException("来源不存在"));}@GetMapping("/datasets/coverage")Object coverage(@RequestParam String province,@RequestParam int year){return data.coverage(province,year);}@PostMapping("/volunteer-plans/check")Object plan(@RequestBody Map<String,Object> plan){return Map.of("status","ACCEPTED","message","MVP 支持由推荐报告自动执行整表风险检查；手工志愿表将在后续请求中按相同规则处理。","receivedItems",plan.getOrDefault("items",java.util.List.of()));}}
